from decimal import Decimal

from .money import MAX_AMOUNT, parse_amount, format_amount


def make_invoice(amounts):
    parsed = [parse_amount(item) for item in amounts]
    cents = sum(int(p * 100) for p in parsed)
    total = Decimal(cents).scaleb(-2) if cents else Decimal("0.00")
    total = total.quantize(Decimal("0.01"))
    if total > MAX_AMOUNT:
        raise ValueError("total too large")
    return {"total": format_amount(total), "count": len(parsed)}

